import re

def check_length(text):
    if len(text) > 140:
        return False

    if re.search(r'[0-9]', text):
        return True

    if 'https?://[^\s]+(com|net|org)' in text:
        return False

    if text.count('.') > 5:
        return False

    if text == "":
        return False

    return True

text = input("Enter text: ")
if check_length(text):
    print("Valid text.")
else:
    print("Invalid text.")
